const PALETTE = ["#f36d3d", "#56b3a3", "#7aa2f7", "#f4c95d", "#c792ea", "#8bd49c"];

function escapeXml(value) {
  return value.replace(/[&<>"']/gu, (character) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&apos;",
  })[character]);
}

function lines(value, maximum = 26) {
  const words = value.split(/\s+/u);
  const output = [];
  let current = "";
  for (const word of words) {
    const candidate = current ? `${current} ${word}` : word;
    if (candidate.length > maximum && current) {
      output.push(current);
      current = word;
    } else {
      current = candidate;
    }
  }
  if (current) output.push(current);
  return output.slice(0, 3);
}

function textLines(value, x, y, options = {}) {
  const {
    fill = "#eef4f7",
    fontSize = 34,
    fontWeight = 500,
    lineHeight = Math.round(fontSize * 1.24),
    anchor = "middle",
    maximum = 28,
  } = options;
  return `<text x="${x}" y="${y}" text-anchor="${anchor}" fill="${fill}" font-family="Arial, Helvetica, sans-serif" font-size="${fontSize}" font-weight="${fontWeight}">${lines(value, maximum).map((line, index) => `<tspan x="${x}" dy="${index === 0 ? 0 : lineHeight}">${escapeXml(line)}</tspan>`).join("")}</text>`;
}

function node([label, detail], x, y, width, height, index) {
  const colour = PALETTE[index % PALETTE.length];
  return [
    `<g class="node">`,
    `<rect x="${x}" y="${y}" width="${width}" height="${height}" rx="32" fill="#121c25" stroke="${colour}" stroke-width="5"/>`,
    `<circle cx="${x + 48}" cy="${y + 48}" r="16" fill="${colour}"/>`,
    textLines(label, x + width / 2, y + 74, { fill: colour, fontSize: 30, fontWeight: 750, maximum: 22 }),
    textLines(detail, x + width / 2, y + 142, { fill: "#c7d0d7", fontSize: 27, fontWeight: 450, maximum: 27 }),
    `</g>`,
  ].join("");
}

function arrow(x1, y1, x2, y2, dashed = false) {
  return `<path d="M ${x1} ${y1} L ${x2} ${y2}" fill="none" stroke="#627381" stroke-width="6" ${dashed ? 'stroke-dasharray="14 14"' : ""} marker-end="url(#arrow)"/>`;
}

function renderFlow(spec) {
  const count = spec.nodes.length;
  const gap = 56;
  const width = Math.floor((1840 - gap * (count - 1)) / count);
  const y = 485;
  const height = 280;
  const start = 200;
  const arrows = [];
  const nodes = [];
  for (let index = 0; index < count; index += 1) {
    const x = start + index * (width + gap);
    nodes.push(node(spec.nodes[index], x, y, width, height, index));
    if (index > 0) arrows.push(arrow(x - gap + 10, y + height / 2, x - 18, y + height / 2));
  }
  return arrows.join("") + nodes.join("");
}

function renderCycle(spec) {
  const positions = [[310, 360], [1390, 360], [1390, 790], [310, 790]];
  const width = 540;
  const height = 220;
  const centers = positions.map(([x, y]) => [x + width / 2, y + height / 2]);
  const arrows = [
    arrow(centers[0][0] + 280, centers[0][1], centers[1][0] - 300, centers[1][1]),
    arrow(centers[1][0], centers[1][1] + 120, centers[2][0], centers[2][1] - 140),
    arrow(centers[2][0] - 280, centers[2][1], centers[3][0] + 300, centers[3][1]),
    arrow(centers[3][0], centers[3][1] - 120, centers[0][0], centers[0][1] + 140, true),
  ];
  return arrows.join("") + positions.map(([x, y], index) => node(spec.nodes[index], x, y, width, height, index)).join("");
}

function renderHub(spec) {
  const centerX = 1120;
  const centerY = 690;
  const centerWidth = 500;
  const centerHeight = 220;
  const radiusX = 760;
  const radiusY = 270;
  const count = spec.nodes.length;
  const elements = [];
  for (let index = 0; index < count; index += 1) {
    const angle = (-Math.PI / 2) + (index * Math.PI * 2) / count;
    const x = centerX + Math.cos(angle) * radiusX;
    const y = centerY + Math.sin(angle) * radiusY;
    elements.push(arrow(centerX, centerY, x, y, true));
  }
  for (let index = 0; index < count; index += 1) {
    const angle = (-Math.PI / 2) + (index * Math.PI * 2) / count;
    const x = centerX + Math.cos(angle) * radiusX - 230;
    const y = centerY + Math.sin(angle) * radiusY - 92;
    elements.push(node(spec.nodes[index], x, y, 460, 184, index));
  }
  elements.push(node(spec.center, centerX - centerWidth / 2, centerY - centerHeight / 2, centerWidth, centerHeight, count));
  return elements.join("");
}

function renderBranch(spec) {
  const root = { x: 150, y: 535, width: 460, height: 230 };
  const branch = { x: 875, width: 500, height: 190 };
  const sink = { x: 1630, y: 535, width: 460, height: 230 };
  const ys = spec.branches.length === 2 ? [390, 740] : [310, 560, 810];
  const elements = [];
  for (const y of ys) {
    elements.push(arrow(root.x + root.width, root.y + root.height / 2, branch.x - 25, y + branch.height / 2));
    elements.push(arrow(branch.x + branch.width, y + branch.height / 2, sink.x - 25, sink.y + sink.height / 2));
  }
  elements.push(node(spec.root, root.x, root.y, root.width, root.height, 0));
  spec.branches.forEach((value, index) => elements.push(node(value, branch.x, ys[index], branch.width, branch.height, index + 1)));
  elements.push(node(spec.sink, sink.x, sink.y, sink.width, sink.height, spec.branches.length + 1));
  return elements.join("");
}

function renderLanes(spec) {
  const x = 240;
  const width = 1760;
  const height = 126;
  const gap = 30;
  const y = 320;
  const arrows = [];
  const elements = [];
  spec.nodes.forEach((value, index) => {
    const currentY = y + index * (height + gap);
    if (index > 0) arrows.push(arrow(1120, currentY - gap + 4, 1120, currentY - 10));
    const colour = PALETTE[index % PALETTE.length];
    elements.push(
      `<g class="lane">`,
      `<rect x="${x}" y="${currentY}" width="${width}" height="${height}" rx="32" fill="#121c25" stroke="${colour}" stroke-width="5"/>`,
      `<circle cx="${x + 50}" cy="${currentY + height / 2}" r="16" fill="${colour}"/>`,
      textLines(value[0], x + 500, currentY + 76, { fill: colour, fontSize: 29, fontWeight: 750, maximum: 28 }),
      textLines(value[1], x + 1210, currentY + 75, { fill: "#c7d0d7", fontSize: 26, fontWeight: 450, maximum: 42 }),
      `</g>`,
    );
  });
  return arrows.join("") + elements.join("");
}

function renderScope(spec) {
  const elements = [
    `<rect x="230" y="330" width="1190" height="620" rx="90" fill="#101b23" stroke="#56b3a3" stroke-width="6"/>`,
    textLines("DECLARED CHANGE SCOPE", 825, 410, { fill: "#56b3a3", fontSize: 31, fontWeight: 750, maximum: 40 }),
    node(spec.inside[0], 330, 500, 460, 250, 0),
    node(spec.inside[1], 860, 500, 460, 250, 1),
    `<path d="M 1470 315 L 2030 315 L 2030 970 L 1470 970 Z" fill="none" stroke="#627381" stroke-width="5" stroke-dasharray="18 16"/>`,
    textLines("PRESERVED OUTSIDE SCOPE", 1750, 400, { fill: "#9eabb5", fontSize: 28, fontWeight: 750, maximum: 36 }),
    node(spec.outside[0], 1540, 485, 420, 190, 3),
    node(spec.outside[1], 1540, 730, 420, 190, 4),
  ];
  return elements.join("");
}

function renderDiagram(spec) {
  const body = spec.layout === "flow"
    ? renderFlow(spec)
    : spec.layout === "cycle"
      ? renderCycle(spec)
      : spec.layout === "hub"
        ? renderHub(spec)
        : spec.layout === "lanes"
          ? renderLanes(spec)
          : spec.layout === "scope"
            ? renderScope(spec)
            : renderBranch(spec);

  return Buffer.from(`<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="${WIDTH}" height="${HEIGHT}" viewBox="0 0 ${WIDTH} ${HEIGHT}">
  <defs>
    <linearGradient id="background" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="#0a1117"/>
      <stop offset="1" stop-color="#111e28"/>
    </linearGradient>
    <pattern id="grid" width="56" height="56" patternUnits="userSpaceOnUse">
      <path d="M 56 0 L 0 0 0 56" fill="none" stroke="#263844" stroke-width="1" opacity="0.45"/>
    </pattern>
    <marker id="arrow" markerWidth="12" markerHeight="12" refX="9" refY="6" orient="auto">
      <path d="M 0 0 L 12 6 L 0 12 z" fill="#627381"/>
    </marker>
  </defs>
  <rect width="2240" height="1260" fill="url(#background)"/>
  <rect width="2240" height="1260" fill="url(#grid)"/>
  <rect x="70" y="60" width="2100" height="1140" rx="44" fill="none" stroke="#344955" stroke-width="3"/>
  <text x="120" y="132" fill="#f36d3d" font-family="Arial, Helvetica, sans-serif" font-size="27" font-weight="750" letter-spacing="3">COURSE 2 · ORIGINAL ABSTRACT MODEL · ${escapeXml(spec.id.toUpperCase())}</text>
  ${textLines(spec.title, 1120, 218, { fill: "#f4f0e8", fontSize: 54, fontWeight: 760, maximum: 64 })}
  ${textLines(spec.subtitle, 1120, 280, { fill: "#aebbc4", fontSize: 28, fontWeight: 450, maximum: 94 })}
  ${body}
  <line x1="120" y1="1110" x2="2120" y2="1110" stroke="#344955" stroke-width="3"/>
  <text x="1120" y="1168" text-anchor="middle" fill="#f4c95d" font-family="Arial, Helvetica, sans-serif" font-size="25" font-weight="750" letter-spacing="2">${escapeXml(CODEX_ORIGINAL_DIAGRAM_LABEL)}</text>
</svg>`);
}

function digest(bytes) {
  return createHash("sha256").update(bytes).digest("hex");
}

function stripPngAncillaryChunks(bytes) {
  const signature = bytes.subarray(0, 8);
  const chunks = [signature];
  let offset = 8;
  while (offset < bytes.length) {
    const length = bytes.readUInt32BE(offset);
    const end = offset + 12 + length;
    if (end > bytes.length) throw new Error("Renderer produced a truncated PNG chunk.");
    const type = bytes.toString("ascii", offset + 4, offset + 8);
    if (["IHDR", "IDAT", "IEND"].includes(type)) chunks.push(bytes.subarray(offset, end));
    offset = end;
  }
  return Buffer.concat(chunks);
}

function outputDirectoryFromArgs() {
  const index = process.argv.indexOf("--output-directory");
  if (index === -1) return DEFAULT_OUTPUT_DIRECTORY;
  const requested = process.argv[index + 1];
  if (!requested || requested.startsWith("--")) {
    throw new Error("--output-directory requires one explicit path.");
  }
  return resolve(requested);
}

async function renderAll(outputDirectory) {
  await mkdir(outputDirectory, { recursive: true });
  const records = [];
  for (const spec of DIAGRAMS) {
    const svg = renderDiagram(spec);
    const encodedMaster = await sharp(svg, { density: 144 })
      .resize(WIDTH, HEIGHT, { fit: "fill" })
      .flatten({ background: "#0a1117" })
      .removeAlpha()
      .png({ compressionLevel: 9, adaptiveFiltering: true, palette: false, quality: 100 })
      .toBuffer();
    const master = stripPngAncillaryChunks(encodedMaster);
    const webp2240 = await sharp(master).webp({ lossless: true, effort: 6 }).toBuffer();
    const webp1120 = await sharp(master)
      .resize(1120, 630, { fit: "fill" })
      .webp({ lossless: true, effort: 6 })
      .toBuffer();
    const assets = {
      png2240: { name: `${spec.id}-master.png`, bytes: master },
      webp2240: { name: `${spec.id}-2240.webp`, bytes: webp2240 },
      webp1120: { name: `${spec.id}-1120.webp`, bytes: webp1120 },
    };
    for (const asset of Object.values(assets)) await writeFile(join(outputDirectory, asset.name), asset.bytes);
    records.push({
      id: spec.id,
      title: spec.title,
      width: WIDTH,
      height: HEIGHT,
      assetSha256: Object.fromEntries(Object.entries(assets).map(([role, asset]) => [role, digest(asset.bytes)])),
    });
  }
  return records;
}

const invokedPath = process.argv[1] ? resolve(process.argv[1]) : "";
if (invokedPath === fileURLToPath(import.meta.url)) {
  const records = await renderAll(outputDirectoryFromArgs());
  const rendererBytes = await readFile(fileURLToPath(import.meta.url));
  process.stdout.write(`${JSON.stringify({
    rendererVersion: CODEX_ORIGINAL_DIAGRAM_RENDERER_VERSION,
    rendererSha256: digest(rendererBytes),
    environment: RENDER_ENVIRONMENT,
    records,
  }, null, 2)}\n`);
}
